	/**
	 * Deletes everything from site meta matching meta key.
	 *
	 * @since 5.1.0
	 *
	 * @param string $meta_key Metadata key to search for when deleting.
	 * @return bool Whether the site meta key was deleted from the database.
	 */
	public function delete_site_meta_by_key( $meta_key );

	/**
	 * Updates metadata cache for list of site IDs.
	 *
	 * Performs SQL query to retrieve all metadata for the sites matching `$site_ids` and stores them in the cache.
	 * Subsequent calls to `get_site_meta()` will not need to query the database.
	 *
	 * @since 5.1.0
	 *
	 * @param array $site_ids List of site IDs.
	 * @return array|false An array of metadata on success, false if there is nothing to update.
	 */
	public function update_sitemeta_cache( $site_ids );

	/**
	 * Queue site meta for lazy-loading.
	 *
	 * @since 6.3.0
	 *
	 * @param array $site_ids List of site IDs.
	 */
	public function wp_lazyload_site_meta( array $site_ids );

	/**
	 * Aborts calls to site meta if it is not supported.
	 *
	 * @since 5.1.0
	 *
	 * @global wpdb $wpdb WordPress database abstraction object.
	 *
	 * @param mixed $check Skip-value for whether to proceed site meta function execution.
	 * @return mixed Original value of $check, or false if site meta is not supported.
	 */
	public function wp_check_site_meta_support_prefilter( $check );

	/**
	 * Gets a blog post from any site on the network.
	 *
	 * This function is similar to get_post(), except that it can retrieve a post
	 * from any site on the network, not just the current site.
	 *
	 * @since MU (3.0.0)
	 *
	 * @param int $blog_id ID of the blog.
	 * @param int $post_id ID of the post being looked for.
	 * @return WP_Post|null WP_Post object on success, null on failure
	 */
	public function get_blog_post( $blog_id, $post_id );

	/**
	 * Gets the permalink for a post on another blog.
	 *
	 * @since MU (3.0.0) 1.0
	 *
	 * @param int $blog_id ID of the source blog.
	 * @param int $post_id ID of the desired post.
	 * @return string The post's permalink.
	 */
	public function get_blog_permalink( $blog_id, $post_id );

	/**
	 * Returns the upload quota for the current blog.
	 *
	 * @since MU (3.0.0)
	 *
	 * @return int Quota in megabytes.
	 */
	public function get_space_allowed();

	/**
	 * Returns the space used by the current site.
	 *
	 * @since 3.5.0
	 *
	 * @return int Used space in megabytes.
	 */
	public function get_space_used();

	/**
	 * Determines if there is any upload space left in the current blog's quota.
	 *
	 * @since 3.0.0
	 *
	 * @return int of upload space available in bytes.
	 */
	public function get_upload_space_available();

	/**
	 * Determines if there is any upload space left in the current blog's quota.
	 *
	 * @since 3.0.0
	 * @return bool True if space is available, false otherwise.
	 */
	public function is_upload_space_available();

	/**
	 * Checks whether a site has used its allotted upload space.
	 *
	 * @since MU (3.0.0)
	 *
	 * @param bool $display_message Optional. If set to true and the quota is exceeded,
	 *                              a warning message is displayed. Default true.
	 * @return bool True if user is over upload space quota, otherwise false.
	 */
	public function upload_is_user_over_quota( $display_message = true );

	/**
	 * Displays the amount of disk space used by the current site. Not used in core.
	 *
	 * @since MU (3.0.0)
	 */
	public function display_space_usage();

	/**
	 * Updates sites in cache.
	 *
	 * @since 4.6.0
	 * @since 5.1.0 Introduced the `$update_meta_cache` parameter.
	 *
	 * @param array $sites             Array of site objects.
	 * @param bool  $update_meta_cache Whether to update site meta cache. Default true.
	 */
	public function update_site_cache( $sites, $update_meta_cache = true );

	/**
	 * Clean the blog cache
	 *
	 * @since 3.5.0
	 *
	 * @global bool $_wp_suspend_cache_invalidation
	 *
	 * @param WP_Site|int $blog The site object or ID to be cleared from cache.
	 */
	public function clean_blog_cache( $blog );

	/**
	 * Cleans the site details cache for a site.
	 *
	 * @since 4.7.4
	 *
	 * @param int $site_id Optional. Site ID. Default is the current site ID.
	 */
	public function clean_site_details_cache( $site_id = 0 );

	/**
	 * Sets the last changed time for the 'sites' cache group.
	 *
	 * @since 5.1.0
	 */
	public function wp_cache_set_sites_last_changed();

	/**
	 * Determines whether Multisite is enabled.
	 *
	 * @since 3.0.0
	 *
	 * @return bool True if Multisite is enabled, false otherwise.
	 */
	public function is_multisite();

	/**
	 * Retrieves the current site ID.
	 *
	 * @since 3.1.0
	 *
	 * @global int $blog_id
	 *
	 * @return int Site ID.
	 */
	public function get_current_blog_id();

	/**
	 * Gets the main site ID.
	 *
	 * @since 4.9.0
	 *
	 * @param int $network_id Optional. The ID of the network for which to get the main site.
	 *                        Defaults to the current network.
	 * @return int The ID of the main site.
	 */
	public function get_main_site_id( $network_id = null );

	/**
	 * Determines whether a site is the main site of the current network.
	 *
	 * @since 3.0.0
	 * @since 4.9.0 The `$network_id` parameter was added.
	 *
	 * @param int $site_id    Optional. Site ID to test. Defaults to current site.
	 * @param int $network_id Optional. Network ID of the network to check for.
	 *                        Defaults to current network.
	 * @return bool True if $site_id is the main site of the network, or if not
	 *              running Multisite.
	 */
	public function is_main_site( $site_id = null, $network_id = null );

	/**
	 * Determines whether site meta is enabled.
	 *
	 * This function checks whether the 'blogmeta' database table exists. The result is saved as
	 * a setting for the main network, making it essentially a global setting. Subsequent requests
	 * will refer to this setting instead of running the query.
	 *
	 * @since 5.1.0
	 *
	 * @global wpdb $wpdb WordPress database abstraction object.
	 *
	 * @return bool True if site meta is supported, false otherwise.
	 */
	public function is_site_meta_supported();
}
